func mustApplyLines(t *testing.T, model *Model, lines ...string) []Action {
	t.Helper()

	var actions []Action
	for _, line := range lines {
		next, err := model.ApplyLine(line)
		if err != nil {
			t.Fatalf("ApplyLine(%q): %v", line, err)
		}
		actions = append(actions, next...)
	}
	return actions
}

func windowLayoutsFromJSON(t *testing.T, snapshot remotegrid.WorkspaceSnapshot) []string {
	t.Helper()

	data, err := json.Marshal(snapshot)
	if err != nil {
		t.Fatal(err)
	}
	var decoded struct {
		Windows []struct {
			Layout string `json:"layout"`
		} `json:"windows"`
	}
	if err := json.Unmarshal(data, &decoded); err != nil {
		t.Fatal(err)
	}
	layouts := make([]string, len(decoded.Windows))
	for index, window := range decoded.Windows {
		layouts[index] = window.Layout
	}
	return layouts
}

func paneIDs(panes []remotegrid.WorkspacePane) []int {
	ids := make([]int, len(panes))
	for i, pane := range panes {
		ids[i] = pane.PaneID
	}
	return ids
}

func windowIDs(windows []remotegrid.WorkspaceWindow) []int {
	ids := make([]int, len(windows))
	for i, window := range windows {
		ids[i] = window.WindowID
	}
	return ids
}

import Foundation
import GhosttyKit

/// Coalesces tmux output data and limits to ONE in-flight
/// `ghostty_surface_inject_output` call at a time.
///
/// Ghostty's internal termio mailbox uses a BlockingQueue(64). When the queue
/// is full, `push()` blocks BEFORE `notify()` fires, so the io thread never
/// wakes to drain it — a deadlock. Without coalescing, a burst of `%output`
/// events dispatches dozens of concurrent inject calls that immediately fill
/// the queue. With coalescing, queue occupancy stays at 0-1 per surface.
///
/// **Threading contract:** `enqueue(_:)` must be called from the main thread.
/// The actual inject call is dispatched to a private serial queue.
final class CoalescingInjector {
    private let queue: DispatchQueue
    private var buffer = Data()
    private var inFlight = false
    private weak var surface: Ghostty.SurfaceView?

    init(paneID: Int, surface: Ghostty.SurfaceView? = nil) {
        self.queue = DispatchQueue(label: "com.fantastty.tmux-inject-pane-\(paneID)")
        self.surface = surface
    }

    func updateSurface(_ surface: Ghostty.SurfaceView) {
        self.surface = surface
    }

    /// Append output data and kick the drain loop if idle.
    /// Must be called from the main thread.
    func enqueue(_ data: Data) {
        buffer.append(data)
        drainIfIdle()
    }

    func cancel() {
        buffer.removeAll()
        surface = nil
    }

    // MARK: - Private

    private func drainIfIdle() {
        guard !inFlight, !buffer.isEmpty else { return }
        guard let surface, surface.surface != nil else {
            buffer.removeAll()
            return
        }

        inFlight = true
        let chunk = buffer
        buffer = Data()

        queue.async { [weak self, weak surface] in
            if let surface, let cSurface = surface.surface {
                chunk.withUnsafeBytes { buf in
                    guard let ptr = buf.baseAddress?.assumingMemoryBound(to: CChar.self) else { return }
                    ghostty_surface_inject_output(cSurface, ptr, UInt(buf.count))
                }
            }
            DispatchQueue.main.async { [weak self] in
                self?.inFlight = false
                self?.drainIfIdle()
            }
        }
    }
}

import XCTest
@testable import Fantastty

final class SessionLauncherModelTests: XCTestCase {
    func testSSHConnectionNormalizesDefaultPort() {
        let draft = SessionLauncherConnectionDraft(host: " remote.example.invalid ", user: " jesse ", port: "22", useRemoteEngine: false)

        let host = draft.sshHostInfo

        XCTAssertEqual(host, SSHHostInfo(user: "jesse", hostname: "remote.example.invalid", port: nil))
    }

    func testSSHConnectionRejectsBlankHost() {
        let draft = SessionLauncherConnectionDraft(host: " ", user: "jesse", port: "22", useRemoteEngine: false)

        XCTAssertNil(draft.sshHostInfo)
        XCTAssertFalse(draft.canDiscover)
    }

    func testSSHConnectionRejectsInvalidPort() {
        let draft = SessionLauncherConnectionDraft(host: "remote.example.invalid", user: "", port: "nope", useRemoteEngine: false)

        XCTAssertNil(draft.sshHostInfo)
        XCTAssertFalse(draft.canDiscover)
    }

    func testSessionRowsStartWithNewSession() {
        let rows = SessionLauncherSessionList.rows(
            for: [
                .tmux(name: "steady-pine", host: .local, windowCount: 3),
                .tmux(name: "release-work", host: .local, windowCount: 1),
            ],
            attachedKeys: []
        )

        XCTAssertEqual(rows.map(\.title), ["New session", "steady-pine", "release-work"])
        XCTAssertEqual(rows.first?.selection, .newSession)
    }

    func testEmptyExistingSessionsStillShowsNewSessionOnly() {
        let rows = SessionLauncherSessionList.rows(
            for: [],
            attachedKeys: []
        )

        XCTAssertEqual(rows.map(\.title), ["New session"])
        XCTAssertEqual(rows.first?.selection, .newSession)
    }

    func testAttachedSessionsAreFilteredFromExistingRows() {
        let rows = SessionLauncherSessionList.rows(
            for: [
                .tmux(name: "steady-pine", host: .local, windowCount: 3),
                .tmux(name: "release-work", host: .local, windowCount: 1),
            ],
            attachedKeys: [
                AttachedSessionKey(sessionName: "steady-pine", host: .local)
            ]
        )

        XCTAssertEqual(rows.map(\.title), ["New session", "release-work"])
    }

    func testFilterMatchesSessionNameAndHost() {
        let sessions = [
            SessionLauncherDiscoveredSession.tmux(name: "steady-pine", host: .local, windowCount: 3),
            .tmux(
                name: "build",
                host: .ssh(SSHHostInfo(user: "jesse", hostname: "magic-kingdom", port: nil)),
                windowCount: 1
            ),
        ]
        let nameRows = SessionLauncherSessionList.rows(
            for: sessions,
            attachedKeys: [],
            filter: "steady"
        )
        let hostRows = SessionLauncherSessionList.rows(
            for: sessions,
            attachedKeys: [],
            filter: "magic"
        )

        XCTAssertEqual(nameRows.map(\.title), ["New session", "steady-pine"])
        XCTAssertEqual(hostRows.map(\.title), ["New session", "build"])
    }

    func testLocalDiscoveryMapsTmuxSessions() {
        let sessions = SessionLauncherDiscovery.discoveredSessions(
            location: .local,
            sshHost: nil,
            listLocalTmux: {
                [
                    TmuxSessionInfo(name: "alpha", createdAt: .distantPast, windowCount: 2),
                    TmuxSessionInfo(name: "beta", createdAt: .distantPast, windowCount: 1),
                ]
            },
            listRemoteTmux: { _ in
                XCTFail("Remote discovery should not be used for local sessions")
                return []
            },
            listSprites: {
                XCTFail("Sprite discovery should not be used for local sessions")
                return []
            }
        )

        XCTAssertEqual(sessions, [
            .tmux(name: "alpha", host: .local, windowCount: 2),
            .tmux(name: "beta", host: .local, windowCount: 1),
        ])
    }

    func testRemoteDiscoveryRequiresValidHost() {
        let sessions = SessionLauncherDiscovery.discoveredSessions(
            location: .ssh,
            sshHost: nil,
            listLocalTmux: {
                XCTFail("Local discovery should not be used for SSH sessions")
                return []
            },
            listRemoteTmux: { _ in
                XCTFail("Remote discovery should not run without a valid host")
                return []
            },
            listSprites: {
                XCTFail("Sprite discovery should not be used for SSH sessions")
                return []
            }
        )

        XCTAssertTrue(sessions.isEmpty)
    }

    func testSpriteDiscoveryMapsSprites() {
        let sessions = SessionLauncherDiscovery.discoveredSessions(
            location: .sprite,
            sshHost: nil,
            listLocalTmux: {
                XCTFail("Local discovery should not be used for Sprite sessions")
                return []
            },
            listRemoteTmux: { _ in
                XCTFail("Remote discovery should not be used for Sprite sessions")
                return []
            },
            listSprites: {
                [
                    SpriteInfo(name: "api"),
                    SpriteInfo(name: "worker"),
                ]
            }
        )

        XCTAssertEqual(sessions, [
            .sprite(name: "api"),
            .sprite(name: "worker"),
        ])
    }

    func testExistingSSHSessionUsesRemoteEngineTransportWhenChecked() {
        let host = SSHHostInfo(user: "jesse", hostname: "remote.example.invalid", port: nil)
        let action = SessionLauncherAction.existingTmuxAction(
            name: "steady-pine",
            host: .ssh(host),
            useRemoteEngine: true
        )

        XCTAssertEqual(action, .attachTmux(TmuxAttachmentInfo(
            sessionName: "steady-pine",
            host: .ssh(host),
            connectionState: .disconnected(reason: nil),
            launchMode: .attach,
            transport: .remoteEngine
        )))
    }

    func testExistingSSHSessionUsesTmuxControlWhenRemoteEngineUnchecked() {
        let host = SSHHostInfo(user: nil, hostname: "remote.example.invalid", port: 2222)
        let action = SessionLauncherAction.existingTmuxAction(
            name: "steady-pine",
            host: .ssh(host),
            useRemoteEngine: false
        )

        XCTAssertEqual(action, .attachTmux(TmuxAttachmentInfo(
            sessionName: "steady-pine",
            host: .ssh(host),
            connectionState: .disconnected(reason: nil),
            launchMode: .attach,
            transport: .tmuxControl
        )))
    }

    func testExistingLocalTmuxAlwaysUsesControlModeTransport() {
        let action = SessionLauncherAction.existingTmuxAction(
            name: "steady-pine",
            host: .local,
            useRemoteEngine: true
        )

        XCTAssertEqual(action, .attachTmux(TmuxAttachmentInfo(
            sessionName: "steady-pine",
            host: .local,
            connectionState: .disconnected(reason: nil),
            launchMode: .attach,
            transport: .tmuxControl
        )))
    }

    func testNewSSHSessionUsesRemoteEngineWhenChecked() {
        let host = SSHHostInfo(user: "jesse", hostname: "remote.example.invalid", port: nil)
        let action = SessionLauncherAction.newSessionAction(
            location: .ssh,
            sshHost: host,
            spriteName: "",
            useRemoteEngine: true
        )

        XCTAssertEqual(action, .createRemoteEngine(host))
    }

    func testNewSSHSessionUsesPlainSSHWhenUnchecked() {
        let host = SSHHostInfo(user: "jesse", hostname: "remote.example.invalid", port: nil)
        let action = SessionLauncherAction.newSessionAction(
            location: .ssh,
            sshHost: host,
            spriteName: "",
            useRemoteEngine: false
        )

        XCTAssertEqual(action, .createSession(.ssh(host: "remote.example.invalid", user: "jesse", port: nil)))
    }

}

package tmuxcc

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"fantastty/remote-engine-helper/remotegrid"
)

type Model struct {
	workspaceID string

	layoutGeneration uint64
	activeWindowID   int
	windows          map[int]*windowState
}

type windowState struct {
	id           int
	title        string
	index        *int
	isActive     bool
	activePaneID int
	panes        map[int]remotegrid.PaneFrame
	layout       string
	hasLayout    bool
}

type Action struct {
	workspaceSnapshot *remotegrid.WorkspaceSnapshot
	paneOutput        *OutputEvent
	paneFlow          *PaneFlowEvent
}

type PaneFlowEvent struct {
	PaneID int
	Paused bool
}

func NewModel(workspaceID string) *Model {
	return &Model{
		workspaceID: workspaceID,
		windows:     make(map[int]*windowState),
	}
}

func (a Action) WorkspaceSnapshot() (remotegrid.WorkspaceSnapshot, bool) {
	if a.workspaceSnapshot == nil {
		return remotegrid.WorkspaceSnapshot{}, false
	}
	return *a.workspaceSnapshot, true
}

func (a Action) PaneOutput() (OutputEvent, bool) {
	if a.paneOutput == nil {
		return OutputEvent{}, false
	}
	return *a.paneOutput, true
}

func (a Action) PaneFlow() (PaneFlowEvent, bool) {
	if a.paneFlow == nil {
		return PaneFlowEvent{}, false
	}
	return *a.paneFlow, true
}

func WorkspaceSnapshotAction(snapshot remotegrid.WorkspaceSnapshot) Action {
	return Action{workspaceSnapshot: &snapshot}
}

func (m *Model) ApplyLine(line string) ([]Action, error) {
	if event, ok, err := ParseOutputLine(line); ok || err != nil {
		if err != nil {
			return nil, err
		}
		return []Action{{paneOutput: &event}}, nil
	}

	fields := strings.Fields(line)
	if len(fields) == 0 {
		return nil, nil
	}

	switch fields[0] {
	case "%pause", "%continue":
		if len(fields) < 2 {
			return nil, fmt.Errorf("tmuxcc: %s missing pane id", fields[0])
		}
		paneID, err := parseTmuxID(fields[1], '%')
		if err != nil {
			return nil, err
		}
		return []Action{{paneFlow: &PaneFlowEvent{
			PaneID: paneID,
			Paused: fields[0] == "%pause",
		}}}, nil
	case "%window-add":
		if len(fields) < 2 {
			return nil, fmt.Errorf("tmuxcc: %%window-add missing window id")
		}
		windowID, err := parseTmuxID(fields[1], '@')
		if err != nil {
			return nil, err
		}
		window := m.ensureWindow(windowID)
		if len(m.windows) == 1 {
			m.setActiveWindow(windowID)
			window.isActive = true
		}
		return nil, nil
	case "%window-renamed":
		if len(fields) < 3 {
			return nil, fmt.Errorf("tmuxcc: %%window-renamed missing fields")
		}
		windowID, err := parseTmuxID(fields[1], '@')
		if err != nil {
			return nil, err
		}
		window := m.ensureWindow(windowID)
		title := strings.TrimSpace(strings.TrimPrefix(line, fields[0]+" "+fields[1]+" "))
		if window.title == title {
			return nil, nil
		}
		window.title = title
		return m.snapshotIfReady()
	case "%window-close", "%unlinked-window-close":
		if len(fields) < 2 {
			return nil, fmt.Errorf("tmuxcc: %s missing window id", fields[0])
		}
		windowID, err := parseTmuxID(fields[1], '@')
		if err != nil {
			return nil, err
		}
		if _, ok := m.windows[windowID]; !ok {
			return nil, nil
		}
		delete(m.windows, windowID)
		if m.activeWindowID == windowID {
			m.activeWindowID = firstWindowID(m.windows)
			m.markActiveWindow()
		}
		return m.snapshotIfReady()
	case "%layout-change":
		if len(fields) < 3 {
			return nil, fmt.Errorf("tmuxcc: %%layout-change missing fields")
		}
		windowID, err := parseTmuxID(fields[1], '@')
		if err != nil {
			return nil, err
		}
		layoutTail := strings.TrimSpace(strings.TrimPrefix(line, fields[0]+" "+fields[1]+" "))
		layout, _, _ := strings.Cut(layoutTail, " ")
		activeMarker := layoutActiveMarker(fields)
		panes, err := parseLayoutPanes(layout)
		if err != nil {
			return nil, err
		}
		window := m.ensureWindow(windowID)
		layoutChanged := !window.hasLayout || window.layout != layout
		activeChanged := false
		if activeMarker == "*" && m.activeWindowID != windowID {
			m.setActiveWindow(windowID)
			activeChanged = true
		}
		if !layoutChanged && !activeChanged {
			return nil, nil
		}
		if layoutChanged {
			window.panes = panes
			window.layout = layout
			window.hasLayout = true
			if _, ok := panes[window.activePaneID]; !ok {
				window.activePaneID = firstPaneID(panes)
			}
		}
		return m.snapshotIfReady()
	case "%window-pane-changed":
		if len(fields) < 3 {
			return nil, fmt.Errorf("tmuxcc: %%window-pane-changed missing fields")
		}
		windowID, err := parseTmuxID(fields[1], '@')
		if err != nil {
			return nil, err
		}
		paneID, err := parseTmuxID(fields[2], '%')
		if err != nil {
			return nil, err
		}
		window := m.ensureWindow(windowID)
		if window.activePaneID == paneID {
			return nil, nil
		}
		window.activePaneID = paneID
		return m.snapshotIfReady()
	case "%session-window-changed":
		if len(fields) < 3 {
			return nil, fmt.Errorf("tmuxcc: %%session-window-changed missing fields")
		}
		windowID, err := parseTmuxID(fields[2], '@')
		if err != nil {
			return nil, err
		}
		if m.activeWindowID == windowID {
			return nil, nil
		}
		m.setActiveWindow(windowID)
		return m.snapshotIfReady()
	default:
		return nil, nil
	}
}

func (m *Model) ApplyListSnapshot(windowLines []string, paneLines []string) ([]Action, error) {
	seed := NewModel(m.workspaceID)
	seed.layoutGeneration = m.layoutGeneration

	activeWindowID := 0
	activeWindowCount := 0
	for _, line := range windowLines {
		fields := strings.Split(line, "\t")
		if len(fields) != 5 {
			return nil, fmt.Errorf("tmuxcc: list-windows line has %d fields, want 5", len(fields))
		}
		windowID, err := parseTmuxID(fields[0], '@')
		if err != nil {
			return nil, err
		}
		panes, err := parseLayoutPanes(fields[2])
		if err != nil {
			return nil, err
		}
		windowIndex, err := strconv.Atoi(fields[3])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid window index %q: %w", fields[3], err)
		}
		active, err := parseTmuxBool(fields[4], "window_active")
		if err != nil {
			return nil, err
		}
		if active {
			activeWindowID = windowID
			activeWindowCount++
		}

		window := seed.ensureWindow(windowID)
		window.title = fields[1]
		window.index = &windowIndex
		window.panes = panes
		window.layout = fields[2]
		window.hasLayout = true
		if _, ok := panes[window.activePaneID]; !ok {
			window.activePaneID = firstPaneID(panes)
		}
	}
	if len(windowLines) > 0 && activeWindowCount != 1 {
		return nil, fmt.Errorf("tmuxcc: list-windows active window count = %d, want 1", activeWindowCount)
	}

	activePanesByWindow := make(map[int]int)
	for _, line := range paneLines {
		fields := strings.Split(line, "\t")
		if len(fields) < 3 {
			return nil, fmt.Errorf("tmuxcc: list-panes line has %d fields, want at least 3", len(fields))
		}
		windowID, err := parseTmuxID(fields[0], '@')
		if err != nil {
			return nil, err
		}
		paneID, err := parseTmuxID(fields[1], '%')
		if err != nil {
			return nil, err
		}
		active, err := parseTmuxBool(fields[2], "pane_active")
		if err != nil {
			return nil, err
		}
		window, ok := seed.windows[windowID]
		if !ok {
			return nil, fmt.Errorf("tmuxcc: list-panes referenced unknown window @%d", windowID)
		}
		if _, ok := window.panes[paneID]; !ok {
			return nil, fmt.Errorf("tmuxcc: list-panes referenced pane %%%d outside window @%d layout", paneID, windowID)
		}
		if active {
			activePanesByWindow[windowID]++
			if activePanesByWindow[windowID] > 1 {
				return nil, fmt.Errorf("tmuxcc: list-panes window @%d has multiple active panes", windowID)
			}
			window.activePaneID = paneID
		}
	}

	if activeWindowCount == 1 {
		seed.setActiveWindow(activeWindowID)
	}
	*m = *seed
	return m.snapshotIfReady()
}

func (m *Model) ensureWindow(windowID int) *windowState {
	if window, ok := m.windows[windowID]; ok {
		return window
	}
	window := &windowState{
		id:    windowID,
		title: fmt.Sprintf("@%d", windowID),
		panes: make(map[int]remotegrid.PaneFrame),
	}
	m.windows[windowID] = window
	if len(m.windows) == 1 {
		m.activeWindowID = windowID
		window.isActive = true
	}
	return window
}

func (m *Model) setActiveWindow(windowID int) {
	m.activeWindowID = windowID
	m.ensureWindow(windowID)
	m.markActiveWindow()
}

func (m *Model) markActiveWindow() {
	for id, window := range m.windows {
		window.isActive = id == m.activeWindowID
	}
}

func (m *Model) snapshotIfReady() ([]Action, error) {
	if !m.hasAnyLayout() {
		return nil, nil
	}
	m.layoutGeneration++
	snapshot := m.snapshot()
	return []Action{{workspaceSnapshot: &snapshot}}, nil
}

func (m *Model) hasAnyLayout() bool {
	for _, window := range m.windows {
		if window.hasLayout {
			return true
		}
	}
	return false
}

func (m *Model) snapshot() remotegrid.WorkspaceSnapshot {
	windowIDs := make([]int, 0, len(m.windows))
	for windowID := range m.windows {
		windowIDs = append(windowIDs, windowID)
	}
	sort.Ints(windowIDs)

	windows := make([]remotegrid.WorkspaceWindow, 0, len(windowIDs))
	var panes []remotegrid.WorkspacePane
	for _, windowID := range windowIDs {
		window := m.windows[windowID]
		windows = append(windows, remotegrid.WorkspaceWindow{
			WindowID: window.id,
			Title:    window.title,
			Index:    window.index,
			IsActive: window.isActive,
			Layout:   window.layout,
		})
		paneIDs := make([]int, 0, len(window.panes))
		for paneID := range window.panes {
			paneIDs = append(paneIDs, paneID)
		}
		sort.Ints(paneIDs)
		for _, paneID := range paneIDs {
			panes = append(panes, remotegrid.WorkspacePane{
				PaneID:   paneID,
				WindowID: window.id,
				IsActive: window.isActive && paneID == window.activePaneID,
				Frame:    window.panes[paneID],
			})
		}
	}

	return remotegrid.WorkspaceSnapshot{
		WorkspaceID:      m.workspaceID,
		LayoutGeneration: m.layoutGeneration,
		Windows:          windows,
		Panes:            panes,
	}
}

var layoutPanePattern = regexp.MustCompile(`(\d+)x(\d+),(\d+),(\d+),%?(\d+)`)

func parseLayoutPanes(layout string) (map[int]remotegrid.PaneFrame, error) {
	matches := layoutPanePattern.FindAllStringSubmatch(layout, -1)
	if len(matches) == 0 {
		return nil, fmt.Errorf("tmuxcc: layout contains no panes: %q", layout)
	}

	panes := make(map[int]remotegrid.PaneFrame, len(matches))
	for _, match := range matches {
		columns, err := strconv.Atoi(match[1])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid pane columns: %w", err)
		}
		rows, err := strconv.Atoi(match[2])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid pane rows: %w", err)
		}
		x, err := strconv.Atoi(match[3])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid pane x: %w", err)
		}
		y, err := strconv.Atoi(match[4])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid pane y: %w", err)
		}
		paneID, err := strconv.Atoi(match[5])
		if err != nil {
			return nil, fmt.Errorf("tmuxcc: invalid pane id: %w", err)
		}
		if columns <= 0 || rows <= 0 {
			return nil, fmt.Errorf("tmuxcc: invalid pane size %dx%d for %%%d", columns, rows, paneID)
		}
		if _, exists := panes[paneID]; exists {
			return nil, fmt.Errorf("tmuxcc: duplicate pane id %%%d", paneID)
		}
		panes[paneID] = remotegrid.PaneFrame{X: x, Y: y, Columns: columns, Rows: rows}
	}
	return panes, nil
}

func parseTmuxID(value string, prefix byte) (int, error) {
	if value == "" || value[0] != prefix {
		return 0, fmt.Errorf("tmuxcc: invalid tmux id %q, want %cN", value, prefix)
	}
	id, err := strconv.Atoi(value[1:])
	if err != nil {
		return 0, fmt.Errorf("tmuxcc: invalid tmux id %q: %w", value, err)
	}
	return id, nil
}

func parseTmuxBool(value string, name string) (bool, error) {
	switch value {
	case "0":
		return false, nil
	case "1":
		return true, nil
	default:
		return false, fmt.Errorf("tmuxcc: invalid %s %q, want 0 or 1", name, value)
	}
}

func layoutActiveMarker(fields []string) string {
	if len(fields) == 0 {
		return ""
	}
	marker := fields[len(fields)-1]
	if marker == "*" || marker == "-" {
		return marker
	}
	return ""
}

func paneLayoutKey(panes map[int]remotegrid.PaneFrame) string {
	ids := make([]int, 0, len(panes))
	for paneID := range panes {
		ids = append(ids, paneID)
	}
	sort.Ints(ids)
	parts := make([]string, len(ids))
	for i, paneID := range ids {
		frame := panes[paneID]
		parts[i] = fmt.Sprintf("%d:%d,%d,%d,%d", paneID, frame.X, frame.Y, frame.Columns, frame.Rows)
	}
	return strings.Join(parts, ",")
}

func firstWindowID(windows map[int]*windowState) int {
	ids := make([]int, 0, len(windows))
	for windowID := range windows {
		ids = append(ids, windowID)
	}
	sort.Ints(ids)
	if len(ids) == 0 {
		return 0
	}
	return ids[0]
}

func firstPaneID(panes map[int]remotegrid.PaneFrame) int {
	ids := make([]int, 0, len(panes))
	for paneID := range panes {
		ids = append(ids, paneID)
	}
	sort.Ints(ids)
	if len(ids) == 0 {
		return 0
	}
	return ids[0]
}

package remotegrid

import (
	"fmt"
	"sort"
)

type PaneModel struct {
	workspaceID string
	paneID      int

	paneGeneration uint64
	keyframeID     uint64
	deltaSequence  uint64
	hasKeyframe    bool

	size        GridSize
	rows        [][]GridCell
	rowVersions []uint64
	dirtyRows   map[int]struct{}

	cursor      CursorState
	cursorDirty bool

	activeScreen ActiveScreen
}

type PaneKeyframeDraft struct {
	workspaceID    string
	paneID         int
	paneGeneration uint64
	keyframeID     uint64
	size           GridSize
	rows           [][]GridCell
	rowVersions    []uint64
	cursor         CursorState
	activeScreen   ActiveScreen
}

func (d PaneKeyframeDraft) WorkspaceID() string {
	return d.workspaceID
}

func (d PaneKeyframeDraft) PaneID() int {
	return d.paneID
}

func (d PaneKeyframeDraft) PaneGeneration() uint64 {
	return d.paneGeneration
}

func (d PaneKeyframeDraft) KeyframeID() uint64 {
	return d.keyframeID
}

func (d PaneKeyframeDraft) Materialize() PaneKeyframe {
	rows := make([]GridRow, len(d.rows))
	for rowIndex, cells := range d.rows {
		rowVersion := uint64(0)
		if rowIndex < len(d.rowVersions) {
			rowVersion = d.rowVersions[rowIndex]
		}
		rows[rowIndex] = GridRow{
			Index:      rowIndex,
			RowVersion: rowVersion,
			Cells:      cloneCells(cells),
		}
	}
	return PaneKeyframe{
		WorkspaceID:                   d.workspaceID,
		PaneID:                        d.paneID,
		PaneGeneration:                d.paneGeneration,
		KeyframeID:                    d.keyframeID,
		GridSize:                      d.size,
		Rows:                          rows,
		Cursor:                        d.cursor,
		ActiveScreen:                  d.activeScreen,
		DatagramsEnabledAfterKeyframe: true,
	}
}

func NewPaneModel(workspaceID string, paneID int, size GridSize) (*PaneModel, error) {
	if err := validateGridSize(size); err != nil {
		return nil, err
	}

	return &PaneModel{
		workspaceID:    workspaceID,
		paneID:         paneID,
		paneGeneration: 1,
		size:           size,
		rows:           newPaneRows(size),
		rowVersions:    make([]uint64, size.Rows),
		dirtyRows:      make(map[int]struct{}),
		cursor:         CursorState{Row: 0, Column: 0, Visible: true, Shape: CursorShapeBlock, CursorVersion: 1},
		activeScreen:   ActiveScreenPrimary,
	}, nil
}

func NewPaneModelFromKeyframe(keyframe PaneKeyframe) (*PaneModel, error) {
	model := &PaneModel{}
	if err := model.ApplyKeyframe(keyframe); err != nil {
		return nil, err
	}
	return model, nil
}

func (p *PaneModel) ApplyKeyframe(keyframe PaneKeyframe) error {
	if err := validateGridSize(keyframe.GridSize); err != nil {
		return err
	}
	if err := validateCursor(keyframe.Cursor, keyframe.GridSize); err != nil {
		return err
	}
	if err := validateActiveScreen(keyframe.ActiveScreen); err != nil {
		return err
	}
	if len(keyframe.Rows) != keyframe.GridSize.Rows {
		return fmt.Errorf("remotegrid: keyframe has %d rows, want %d", len(keyframe.Rows), keyframe.GridSize.Rows)
	}

	rows := newPaneRows(keyframe.GridSize)
	rowVersions := make([]uint64, keyframe.GridSize.Rows)
	seenRows := make([]bool, keyframe.GridSize.Rows)
	for _, row := range keyframe.Rows {
		if row.Index < 0 || row.Index >= keyframe.GridSize.Rows {
			return fmt.Errorf("remotegrid: keyframe row index %d outside grid rows 0..%d", row.Index, keyframe.GridSize.Rows-1)
		}
		if seenRows[row.Index] {
			return fmt.Errorf("remotegrid: duplicate keyframe row %d", row.Index)
		}
		if len(row.Cells) != keyframe.GridSize.Columns {
			return fmt.Errorf("remotegrid: keyframe row %d has %d cells, want %d", row.Index, len(row.Cells), keyframe.GridSize.Columns)
		}
		if err := validateCells(row.Cells); err != nil {
			return fmt.Errorf("remotegrid: keyframe row %d: %w", row.Index, err)
		}
		seenRows[row.Index] = true
		rows[row.Index] = cloneCells(row.Cells)
		rowVersions[row.Index] = row.RowVersion
	}

	p.workspaceID = keyframe.WorkspaceID
	p.paneID = keyframe.PaneID
	p.paneGeneration = keyframe.PaneGeneration
	p.keyframeID = keyframe.KeyframeID
	p.deltaSequence = 0
	p.hasKeyframe = true
	p.size = keyframe.GridSize
	p.rows = rows
	p.rowVersions = rowVersions
	p.dirtyRows = make(map[int]struct{})
	p.cursor = keyframe.Cursor
	p.cursorDirty = false
	p.activeScreen = keyframe.ActiveScreen
	return nil
}

func (p *PaneModel) SetRow(rowIndex int, cells []GridCell) error {
	if rowIndex < 0 || rowIndex >= p.size.Rows {
		return fmt.Errorf("remotegrid: row index %d outside grid rows 0..%d", rowIndex, p.size.Rows-1)
	}
	if len(cells) != p.size.Columns {
		return fmt.Errorf("remotegrid: row %d has %d cells, want %d", rowIndex, len(cells), p.size.Columns)
	}
	if err := validateCells(cells); err != nil {
		return fmt.Errorf("remotegrid: row %d: %w", rowIndex, err)
	}
	if cellsEqual(p.rows[rowIndex], cells) {
		return nil
	}

	p.rows[rowIndex] = cloneCells(cells)
	p.rowVersions[rowIndex]++
	p.dirtyRows[rowIndex] = struct{}{}
	return nil
}

func (p *PaneModel) Keyframe() PaneKeyframe {
	return ClonePaneKeyframe(p.KeyframeDraft())
}

func (p *PaneModel) KeyframeDraft() PaneKeyframe {
	return p.BeginKeyframeDraft().Materialize()
}

func (p *PaneModel) BeginKeyframeDraft() PaneKeyframeDraft {
	p.keyframeID++
	p.deltaSequence = 0
	p.hasKeyframe = true
	p.dirtyRows = make(map[int]struct{})
	p.cursorDirty = false

	return PaneKeyframeDraft{
		workspaceID:    p.workspaceID,
		paneID:         p.paneID,
		paneGeneration: p.paneGeneration,
		keyframeID:     p.keyframeID,
		size:           p.size,
		rows:           append([][]GridCell(nil), p.rows...),
		rowVersions:    append([]uint64(nil), p.rowVersions...),
		cursor:         p.cursor,
		activeScreen:   p.activeScreen,
	}
}

func (p *PaneModel) Delta() (PaneDelta, bool) {
	if !p.hasKeyframe {
		return PaneDelta{}, false
	}
	if len(p.dirtyRows) == 0 && !p.cursorDirty {
		return PaneDelta{}, false
	}

	p.deltaSequence++
	delta := PaneDelta{
		WorkspaceID:    p.workspaceID,
		PaneID:         p.paneID,
		PaneGeneration: p.paneGeneration,
		BaseKeyframeID: p.keyframeID,
		DeltaSequence:  p.deltaSequence,
		RowUpdates:     p.dirtyRowUpdates(),
	}
	if p.cursorDirty {
		cursor := p.cursor
		delta.Cursor = &cursor
	}

	p.dirtyRows = make(map[int]struct{})
	p.cursorDirty = false
	return delta, true
}

func (p *PaneModel) ApplyDelta(delta PaneDelta) (PaneDelta, bool, error) {
	if !p.hasKeyframe {
		return PaneDelta{}, false, nil
	}
	if delta.WorkspaceID != p.workspaceID || delta.PaneID != p.paneID {
		return PaneDelta{}, false, fmt.Errorf("remotegrid: delta for workspace %q pane %d cannot apply to workspace %q pane %d", delta.WorkspaceID, delta.PaneID, p.workspaceID, p.paneID)
	}
	if delta.PaneGeneration != p.paneGeneration {
		return PaneDelta{}, false, nil
	}
	if delta.BaseKeyframeID > p.keyframeID {
		return PaneDelta{}, false, nil
	}

	rows := clonePaneRows(p.rows)
	rowVersions := append([]uint64(nil), p.rowVersions...)
	for _, update := range delta.RowUpdates {
		if err := applyRowUpdate(rows, rowVersions, p.size, update); err != nil {
			return PaneDelta{}, false, err
		}
	}

	cursor := p.cursor
	if delta.Cursor != nil {
		if err := validateCursor(*delta.Cursor, p.size); err != nil {
			return PaneDelta{}, false, err
		}
		if delta.Cursor.CursorVersion > cursor.CursorVersion {
			cursor = *delta.Cursor
		}
	}

	normalized := clonePaneDelta(delta)
	if delta.BaseKeyframeID < p.keyframeID {
		p.deltaSequence++
		normalized.BaseKeyframeID = p.keyframeID
		normalized.DeltaSequence = p.deltaSequence
	} else if delta.DeltaSequence > p.deltaSequence {
		p.deltaSequence = delta.DeltaSequence
	}

	p.rows = rows
	p.rowVersions = rowVersions
	p.cursor = cursor
	p.dirtyRows = make(map[int]struct{})
	p.cursorDirty = false
	return normalized, true, nil
}

func (p *PaneModel) Resize(size GridSize) error {
	if err := validateGridSize(size); err != nil {
		return err
	}
	if p.size == size {
		return nil
	}

	oldRows := p.rows
	p.size = size
	p.rows = newPaneRows(size)
	for rowIndex := range p.rows {
		if rowIndex >= len(oldRows) {
			continue
		}
		columns := len(p.rows[rowIndex])
		if len(oldRows[rowIndex]) < columns {
			columns = len(oldRows[rowIndex])
		}
		copy(p.rows[rowIndex][:columns], oldRows[rowIndex][:columns])
		normalizeCells(p.rows[rowIndex])
	}

	p.rowVersions = make([]uint64, size.Rows)
	p.dirtyRows = make(map[int]struct{})
	p.paneGeneration++
	p.keyframeID = 0
	p.deltaSequence = 0
	p.hasKeyframe = false
	clampedCursor := clampCursor(p.cursor, size)
	if cursorPositionChanged(p.cursor, clampedCursor) {
		clampedCursor.CursorVersion = p.cursor.CursorVersion + 1
	}
	p.cursor = clampedCursor
	p.cursorDirty = false
	return nil
}

func (p *PaneModel) GridSize() GridSize {
	return p.size
}

func (p *PaneModel) PaneGeneration() uint64 {
	return p.paneGeneration
}

func (p *PaneModel) HasKeyframe() bool {
	return p.hasKeyframe
}

func (p *PaneModel) SetActiveScreen(screen ActiveScreen) bool {
	if p.activeScreen == screen {
		return false
	}
	p.activeScreen = screen
	p.rows = newPaneRows(p.size)
	p.rowVersions = make([]uint64, p.size.Rows)
	p.dirtyRows = make(map[int]struct{})
	p.paneGeneration++
	p.keyframeID = 0
	p.deltaSequence = 0
	p.hasKeyframe = false
	p.cursor = CursorState{Row: 0, Column: 0, Visible: true, Shape: CursorShapeBlock, CursorVersion: p.cursor.CursorVersion + 1}
	p.cursorDirty = false
	return true
}

func (p *PaneModel) SetCursor(cursor CursorState) error {
	if err := validateCursor(cursor, p.size); err != nil {
		return err
	}
	cursor.CursorVersion = p.cursor.CursorVersion
	if p.cursor == cursor {
		return nil
	}
	cursor.CursorVersion++
	p.cursor = cursor
	if p.hasKeyframe {
		p.cursorDirty = true
	}
	return nil
}

func (p *PaneModel) snapshotRows() []GridRow {
	return CloneGridRows(p.keyframeRows())
}

func (p *PaneModel) keyframeRows() []GridRow {
	rows := make([]GridRow, len(p.rows))
	for rowIndex := range p.rows {
		rows[rowIndex] = GridRow{
			Index:      rowIndex,
			RowVersion: p.rowVersions[rowIndex],
			Cells:      p.rows[rowIndex],
		}
	}
	return rows
}

func (p *PaneModel) dirtyRowUpdates() []RowUpdate {
	rowIndexes := make([]int, 0, len(p.dirtyRows))
	for rowIndex := range p.dirtyRows {
		rowIndexes = append(rowIndexes, rowIndex)
	}
	sort.Ints(rowIndexes)

	updates := make([]RowUpdate, 0, len(rowIndexes))
	for _, rowIndex := range rowIndexes {
		updates = append(updates, RowUpdate{
			RowIndex:   rowIndex,
			RowVersion: p.rowVersions[rowIndex],
			Update:     FullRow(cloneCells(p.rows[rowIndex])),
		})
	}
	return updates
}

func newPaneRows(size GridSize) [][]GridCell {
	rows := make([][]GridCell, size.Rows)
	for rowIndex := range rows {
		rows[rowIndex] = blankCells(size.Columns)
	}
	return rows
}

func blankCells(columns int) []GridCell {
	cells := make([]GridCell, columns)
	for column := range cells {
		cells[column] = blankCell()
	}
	return cells
}

func cloneCells(cells []GridCell) []GridCell {
	clone := make([]GridCell, len(cells))
	copy(clone, cells)
	return clone
}

func cellsEqual(left, right []GridCell) bool {
	if len(left) != len(right) {
		return false
	}
	for i := range left {
		if left[i] != right[i] {
			return false
		}
	}
	return true
}

func clonePaneRows(rows [][]GridCell) [][]GridCell {
	clone := make([][]GridCell, len(rows))
	for rowIndex := range rows {
		clone[rowIndex] = cloneCells(rows[rowIndex])
	}
	return clone
}

func applyRowUpdate(rows [][]GridCell, rowVersions []uint64, size GridSize, update RowUpdate) error {
	if update.RowIndex < 0 || update.RowIndex >= size.Rows {
		return fmt.Errorf("remotegrid: row update index %d outside grid rows 0..%d", update.RowIndex, size.Rows-1)
	}
	if update.Update.span != nil {
		return applySpanUpdate(rows, rowVersions, size, update)
	}
	return applyFullRowUpdate(rows, rowVersions, size, update)
}

func applyFullRowUpdate(rows [][]GridCell, rowVersions []uint64, size GridSize, update RowUpdate) error {
	cells := update.Update.fullRow
	if len(cells) != size.Columns {
		return fmt.Errorf("remotegrid: full row update %d has %d cells, want %d", update.RowIndex, len(cells), size.Columns)
	}
	if err := validateCells(cells); err != nil {
		return fmt.Errorf("remotegrid: full row update %d: %w", update.RowIndex, err)
	}
	if update.RowVersion <= rowVersions[update.RowIndex] {
		return nil
	}
	rows[update.RowIndex] = cloneCells(cells)
	rowVersions[update.RowIndex] = update.RowVersion
	return nil
}

func applySpanUpdate(rows [][]GridCell, rowVersions []uint64, size GridSize, update RowUpdate) error {
	span := update.Update.span
	if span.StartColumn < 0 || span.StartColumn > size.Columns {
		return fmt.Errorf("remotegrid: span update row %d start column %d outside grid columns 0..%d", update.RowIndex, span.StartColumn, size.Columns)
	}
	endColumn := span.StartColumn + len(span.Cells)
	if len(span.Cells) == 0 {
		return fmt.Errorf("remotegrid: span update row %d has no cells", update.RowIndex)
	}
	if endColumn > size.Columns {
		return fmt.Errorf("remotegrid: span update row %d ends at column %d outside grid columns 0..%d", update.RowIndex, endColumn, size.Columns)
	}
	clearToColumn := endColumn
	if span.ClearToColumn != nil {
		clearToColumn = *span.ClearToColumn
		if clearToColumn < endColumn || clearToColumn > size.Columns {
			return fmt.Errorf("remotegrid: span update row %d clear column %d outside grid columns %d..%d", update.RowIndex, clearToColumn, endColumn, size.Columns)
		}
	}
	if err := validateCells(span.Cells); err != nil {
		return fmt.Errorf("remotegrid: span update row %d: %w", update.RowIndex, err)
	}
	if update.RowVersion <= rowVersions[update.RowIndex] {
		return nil
	}
	if span.BaseRowVersion != rowVersions[update.RowIndex] {
		return fmt.Errorf("remotegrid: span update row %d base row version %d does not match current row version %d", update.RowIndex, span.BaseRowVersion, rowVersions[update.RowIndex])
	}

	row := cloneCells(rows[update.RowIndex])
	copy(row[span.StartColumn:endColumn], span.Cells)
	for column := endColumn; column < clearToColumn; column++ {
		row[column] = blankCell()
	}
	if err := validateCells(row); err != nil {
		return fmt.Errorf("remotegrid: span update row %d: %w", update.RowIndex, err)
	}
	rows[update.RowIndex] = row
	rowVersions[update.RowIndex] = update.RowVersion
	return nil
}

func validateGridSize(size GridSize) error {
	if size.Columns <= 0 || size.Rows <= 0 {
		return fmt.Errorf("remotegrid: invalid grid size %dx%d", size.Columns, size.Rows)
	}
	return nil
}

func validateActiveScreen(screen ActiveScreen) error {
	if screen != ActiveScreenPrimary && screen != ActiveScreenAlternate {
		return fmt.Errorf("remotegrid: unsupported active screen %q", screen)
	}
	return nil
}

func validateCursor(cursor CursorState, size GridSize) error {
	if cursor.Row < 0 || cursor.Row >= size.Rows {
		return fmt.Errorf("remotegrid: cursor row %d outside grid rows 0..%d", cursor.Row, size.Rows-1)
	}
	if cursor.Column < 0 || cursor.Column >= size.Columns {
		return fmt.Errorf("remotegrid: cursor column %d outside grid columns 0..%d", cursor.Column, size.Columns-1)
	}
	if cursor.Shape != CursorShapeBlock && cursor.Shape != CursorShapeBar && cursor.Shape != CursorShapeUnderline {
		return fmt.Errorf("remotegrid: unsupported cursor shape %q", cursor.Shape)
	}
	return nil
}

func clampCursor(cursor CursorState, size GridSize) CursorState {
	if cursor.Row < 0 {
		cursor.Row = 0
	} else if cursor.Row >= size.Rows {
		cursor.Row = size.Rows - 1
	}
	if cursor.Column < 0 {
		cursor.Column = 0
	} else if cursor.Column >= size.Columns {
		cursor.Column = size.Columns - 1
	}
	return cursor
}

func cursorPositionChanged(left CursorState, right CursorState) bool {
	return left.Row != right.Row ||
		left.Column != right.Column ||
		left.Visible != right.Visible ||
		left.Shape != right.Shape
}

func validateCells(cells []GridCell) error {
	for column := 0; column < len(cells); {
		cell := cells[column]
		switch cell.Width {
		case 1:
			column++
		case 2:
			continuationColumn := column + 1
			if continuationColumn >= len(cells) {
				return fmt.Errorf("wide cell at column %d has no continuation cell", column)
			}
			if cells[continuationColumn] != continuationCell() {
				return fmt.Errorf("wide cell at column %d has invalid continuation cell at column %d", column, continuationColumn)
			}
			column += 2
		default:
			return fmt.Errorf("cell at column %d has invalid width %d", column, cell.Width)
		}
	}
	return nil
}

func normalizeCells(cells []GridCell) {
	for column := 0; column < len(cells); {
		cell := cells[column]
		switch cell.Width {
		case 1:
			column++
		case 2:
			continuationColumn := column + 1
			if continuationColumn < len(cells) && cells[continuationColumn] == continuationCell() {
				column += 2
				continue
			}
			cells[column] = blankCell()
			column++
		default:
			cells[column] = blankCell()
			column++
		}
	}
}

func blankCell() GridCell {
	return GridCell{Text: " ", Width: 1, Style: NormalCellStyle}
}

func continuationCell() GridCell {
	return GridCell{Text: "", Width: 0, Style: NormalCellStyle}
}

